<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?><div id="wrapper"><div id="sc-enterprise-app"><div class="content"><div class="sc-enterprise-header"><div><h1><?php echo html_escape($title); ?></h1><p><?php echo _l('enterprise_dispatch_description'); ?></p></div><div class="sc-toolbar"><a class="btn btn-default btn-sm" href="<?php echo current_url(); ?>"><i class="fa fa-refresh"></i> <?php echo _l('reload'); ?></a></div></div><?php if(has_permission(SMART_CHOICE_ENTERPRISE_CORE_MODULE_NAME,'','manage_dispatch')){?><div class="panel_s"><div class="panel-body"><h4><?php echo _l('enterprise_create_dispatch'); ?></h4><form method="post" class="row"><?php echo form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()); ?><div class="col-md-3"><input class="form-control" name="title" required placeholder="<?php echo _l('enterprise_assignment_title'); ?>"></div><div class="col-md-3"><select class="form-control" name="staff_id"><option value=""><?php echo _l('staff_member'); ?></option><?php foreach($staff as $s){?><option value="<?php echo (int)$s['staffid']; ?>"><?php echo html_escape(trim($s['firstname'].' '.$s['lastname'])); ?></option><?php }?></select></div><div class="col-md-3"><select class="form-control" name="project_id"><option value=""><?php echo _l('project'); ?></option><?php foreach($projects as $p){?><option value="<?php echo (int)$p['id']; ?>"><?php echo html_escape($p['name']); ?></option><?php }?></select></div><div class="col-md-2"><input type="datetime-local" class="form-control" name="scheduled_start"></div><div class="col-md-1"><button class="btn btn-primary btn-block"><i class="fa fa-paper-plane"></i></button></div></form></div></div><?php }?><div class="panel_s"><div class="panel-body"><h4><?php echo _l('enterprise_dispatch_assignments'); ?></h4><div class="sc-enterprise-data-wrap"><table class="table table-striped sc-enterprise-table"><thead><tr><?php foreach($assignments['fields'] as $field){?><th><?php echo html_escape(ucwords(str_replace('_',' ',$field))); ?></th><?php }?></tr></thead><tbody><?php foreach($assignments['rows'] as $row){?><tr><?php foreach($assignments['fields'] as $field){?><td><?php echo html_escape($row[$field]??''); ?></td><?php }?></tr><?php }?></tbody></table></div></div></div></div></div></div><?php init_tail(); ?>